import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-1",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 1" disableTooltip>
            <p class="hint">This card sets disableTooltip: its title shows no hint.</p>
            <app-pill label="Plain" hideHint />
            <app-pill variant="success" label="Active" [hideHint]="!isActive" />
            <app-pill [label]="count > 3 ? 'Many' : title" [hideHint]="count > 3" />
            <app-pill
                [variant]="isActive ? 'success' : 'warning'"
                label="Multi-line"
                [hideHint]="isActive">
            </app-pill>
            @if (isActive) {
                <app-pill [variant]="statusVariant" label="Nested" [hideHint]="false" />
            }
            <app-fancy-pill label="Fancy" icon="star" [disableTooltip]="!isActive" />
            @if (disableTooltip) {
                <small>Hints are switched off on this screen</small>
            }
        </app-card>
    `
})
export class Feature001Component {
    isActive = false;
    count = 1;
    title = "Title 1";
    statusVariant: PillVariant = "success";
    // disableTooltip is the switch of this screen; the card and the pills have theirs
    disableTooltip = true;
}

